SELECT 2 AS storage_version,g.account_id AS owner_id,g.vault_id,g.origin,g.collection_id,g.record_id,g.kind,g.record_revision,g.ciphertext_sha256,g.key_generation,g.owner_key_revision,g.version,g.status,g.expires_at FROM vault_record_grant g JOIN vault_owner_key_head root ON root.account_id=g.account_id AND root.vault_id=g.vault_id WHERE g.account_id=?1 AND g.collection_id='personal' AND g.record_id='name' AND g.recipient_service='userinfo' AND g.purpose='oidc.userinfo.name'
